func onKeyPressEvent(_ *_Ctype_GtkWidget, event *_Ctype_GdkEventKey, userData _Ctype_uintptr_t) _Ctype_gboolean {
	repeat := keyRepeats.press(uint(event.hardware_keycode))

	windowID := uint(_Ctype_uint(userData))
	if accelerator, ok := getKeyboardState(event); ok {

		if !repeat {
			windowKeyEvents <- &windowKeyEvent{
				windowId:          windowID,
				acceleratorString: accelerator,
			}
		}

		if accelerator == "Ctrl+Z" || accelerator == "Ctrl+Shift+Z" {
			return _Ctype_gboolean(1)
		}
	}
	return _Ctype_gboolean(0)
}

func getKeyboardState(event *_Ctype_GdkEventKey) (string, bool) {
	modifiers := uint(event.state) & _Ciconst_GDK_MODIFIER_MASK
	keyCode := uint(event.keyval)

	var acc accelerator

	if modifiers&(_Ciconst_GDK_SHIFT_MASK) != 0 {
		acc.Modifiers = append(acc.Modifiers, ShiftKey)
	}
	if modifiers&(_Ciconst_GDK_CONTROL_MASK) != 0 {
		acc.Modifiers = append(acc.Modifiers, ControlKey)
	}
	if modifiers&(_Ciconst_GDK_MOD1_MASK) != 0 {
		acc.Modifiers = append(acc.Modifiers, OptionOrAltKey)
	}
	if modifiers&(_Ciconst_GDK_SUPER_MASK) != 0 {
		acc.Modifiers = append(acc.Modifiers, SuperKey)
	}
	keyString, ok := VirtualKeyCodes[keyCode]
	if !ok {
		return "", false
	}
	acc.Key = keyString
	return acc.String(), true
}

